:host {
    display: block;
    padding-bottom: 1.5rem;
    --rr-blue: #0176d3;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
    --rr-ok: #2e844a;
    --rr-bad: #ba0517;
    --rr-bar: #0b5cab;
    --rr-mono: ui-monospace, Menlo, Consolas, monospace;
}
.rr-page { display: flex; flex-direction: column; gap: 12px; color: var(--rr-ink); }
.rr-page p { margin: 0; }
.rr-card { background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); min-width: 0; }
.rr-pad { padding: 10px 12px; }
.rr-spin { position: relative; min-height: 80px; }
.rr-head { display: flex; align-items: flex-end; gap: 12px; flex-wrap: wrap; padding: 10px 14px; }
.rr-eyebrow { font-size: 12px; color: var(--rr-muted); }
.rr-h1 { font-size: 18px; font-weight: 700; margin: 0; }
.rr-h2 { font-size: 14px; font-weight: 700; margin: 0; }
.rr-h3 { font-size: 13px; font-weight: 700; margin: 12px 0 4px; }
.rr-filters { display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap; margin-left: auto; }
.rr-pick { min-width: 170px; }
.rr-segs { display: inline-flex; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; }
.rr-seg { border: 0; border-right: 1px solid #c9c9c9; background: #fff; color: var(--rr-blue); padding: 6px 11px; font: inherit; font-size: 12px; cursor: pointer; }
.rr-seg:last-child { border-right: 0; }
.rr-seg-on { background: var(--rr-blue); color: #fff; }
.rr-seg:focus-visible { outline: 2px solid var(--rr-blue); outline-offset: -2px; }
.rr-small { font-size: 12px; }
.rr-weak { color: var(--rr-muted); }
.rr-mono { font-family: var(--rr-mono); }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; }
.rr-msg-bad { background: #fef1ee; color: #8e030f; }
.rr-msg-warn { background: #fef1cd; color: #5c3a00; }
.rr-tiles { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 12px; }
.rr-tile { padding: 10px 12px; display: flex; flex-direction: column; gap: 2px; }
.rr-tile-k { font-size: 12px; color: var(--rr-muted); }
.rr-tile-v { font-size: 22px; font-weight: 700; }
.rr-dora { display: inline-block; margin-left: 6px; font-size: 10.5px; font-weight: 700; padding: 1px 7px; border-radius: 9px; background: #eef4ff; color: var(--rr-blue); }
.rr-trend { font-size: 11.5px; }
.rr-up { color: var(--rr-ok); }
.rr-down { color: var(--rr-bad); }
.rr-flat { color: var(--rr-muted); }
.rr-charts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.rr-chart { display: flex; flex-direction: column; }
.rr-chart-h { display: flex; align-items: center; gap: 6px; padding: 10px 12px 0; }
.rr-svg { width: 100%; height: auto; display: block; padding: 4px 8px 6px; }
.rr-axis { stroke: #c9c9c9; stroke-width: 1; }
.rr-val { font-size: 11px; fill: #181818; font-weight: 600; }
.rr-lab { font-size: 10.5px; fill: #5c5c5c; }
.rr-hb { display: grid; grid-template-columns: minmax(120px, 34%) 1fr 36px; gap: 8px; align-items: center; font-size: 12px; margin: 6px 0; }
.rr-hb-l { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-hb-t { height: 12px; background: #eef1f5; border-radius: 3px; overflow: hidden; }
.rr-hb-t i { display: block; height: 100%; background: var(--rr-bar); }
.rr-hb b { text-align: right; }
.rr-note { margin-top: 8px; }
.rr-foot { padding: 0 2px; }
.rr-csv { align-self: center; }
@media (max-width: 1200px) { .rr-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 900px) { .rr-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); } .rr-charts { grid-template-columns: 1fr; } }
